r"""项目 Extract 图片链接审计（只读）。

为什么需要它
------------
`lit_extract.py --no-images` 生成的 Extract 仍会保留 `![](assets/...)` 链接，
但图片文件并未落盘。页面能正常打开、正文可读，**断图只有逐页翻才看得见**。
本工具把「哪些 Extract 有断图、断在第几行、指向哪里」一次列清。

判据
----
- 支持 Markdown `![alt](path)` 与 Obsidian `![[path]]` 两种写法；
- 跳过 `http://` / `https://` / `data:`；
- 相对路径依次尝试：Extract 目录、项目根；
- 目标文件不存在 → 断链。

用法
----
    python tools/qc_proj_assets.py --project projects/myproj-review
    python tools/qc_proj_assets.py --project projects/myproj-review --json
    python tools/qc_proj_assets.py --project projects/myproj-review \
        --write evidence/extract-image-audit.md
    python tools/qc_proj_assets.py --selftest

退出码：0 完成 ｜ 1 参数/环境错误
"""
import argparse
import datetime
import glob
import io
import json
import os
import re
import sys

import yaml

HERE = os.path.dirname(os.path.abspath(__file__))
VAULT = os.path.dirname(HERE)
sys.path.insert(0, HERE)
import kb_lib as K  # noqa: E402

EXTRACT = os.path.join("references", "Extract")
MD_IMG = re.compile(r"!\[([^\]]*)\]\(([^)\s]+)(?:\s+\"[^\"]*\")?\)")
WIKI_IMG = re.compile(r"!\[\[([^\]|#]+)")


def iter_md_images(line):
    """逐条解析 Markdown 图片，**支持目标路径内的成对括号**。

    例：`![](assets/Durable-Multiblock-Poly(biphenyl-alkylene)/fig1.png)`
    简单正则 `\\(([^)]+)\\)` 会在第一个 `)` 截断，把真实路径误报成断链
    （2026-10-23 实测：18 份文件 104 条断链中有多条因此截断）。
    """
    i = 0
    while True:
        k = line.find("![", i)
        if k < 0:
            return
        mid = line.find("](", k + 2)
        if mid < 0:
            return
        alt = line[k + 2:mid]
        j = mid + 2
        depth = 0
        while j < len(line):
            ch = line[j]
            if ch == "(":
                depth += 1
            elif ch == ")":
                if depth == 0:
                    break
                depth -= 1
            j += 1
        if j >= len(line):
            return
        target = line[mid + 2:j].strip()
        if target.startswith("<") and ">" in target:
            target = target[1:target.index(">")]
        elif ' "' in target:
            target = target.split(' "', 1)[0]
        if target:
            yield alt, target
        i = j + 1


def read_text(path):
    return K.read_text(path)


def is_external(target):
    return target.lower().startswith(("http://", "https://", "data:"))


def resolve(project, ext_dir, target):
    """相对 Extract 目录与项目根依次解析；返回存在与否。"""
    t = target.strip().strip("<>").replace("\\", "/")
    if t.startswith("/"):
        return False
    for base in (ext_dir, project):
        p = os.path.normpath(os.path.join(base, t))
        if os.path.exists(p):
            return True
    return False


def scan(project):
    ext_dir = os.path.join(project, EXTRACT)
    files = sorted(glob.glob(os.path.join(ext_dir, "*.md")))
    rows = []
    total = broken = 0
    for path in files:
        rel = os.path.relpath(path, project).replace("\\", "/")
        text = read_text(path)
        for i, line in enumerate(text.split("\n"), 1):
            found = []
            for alt, target in iter_md_images(line):
                if not is_external(target):
                    found.append((target, alt))
            for m in WIKI_IMG.finditer(line):
                target = m.group(1).strip()
                if not is_external(target):
                    found.append((target, ""))
            for target, alt in found:
                total += 1
                if not resolve(project, ext_dir, target):
                    broken += 1
                    rows.append({
                        "extract": rel,
                        "line": i,
                        "target": target,
                        "alt": alt[:60],
                    })
    files_with_links = sum(1 for p in files
                           if any(True for line in read_text(p).split("\n")
                                  for _ in iter_md_images(line))
                           or WIKI_IMG.search(read_text(p)))
    files_broken = len({r["extract"] for r in rows})
    return rows, {
        "extract_files": len(files),
        "files_with_links": files_with_links,
        "files_with_broken": files_broken,
        "image_links": total,
        "broken": broken,
        "valid": total - broken,
    }


def render(project, rows, summary, date_str):
    project_name = os.path.basename(os.path.normpath(project))
    fm = [
        "created: %s" % date_str,
        "updated: %s" % date_str,
        "type: output",
        'title: "Extract 断图链清单：%s"' % project_name,
        "tags: [某工程, Extract, 图片链接, QC, P1-6]",
        'summary: "%s 的 references/Extract/ 只读图片链接审计：%d 份 Extract、%d 个图片链接，'
        '断链 %d 个，分布在 %d 份文件中（其余 %d 个链接可解析）。断链来自提取时使用 '
        '--no-images，图片未落盘，不是正文损坏。"'
        % (project_name, summary["extract_files"], summary["image_links"],
           summary["broken"], summary["files_with_broken"], summary["valid"]),
    ]
    body = []
    body.append("# Extract 断图链清单：%s" % project_name)
    body.append("")
    body.append("> **只读审计**（`tools/qc_proj_assets.py`）。本清单只登记**指向不存在文件**的图片链接，"
                "不修改任何 Extract、不补图、不改写链接。")
    body.append("")
    body.append("## 一、汇总")
    body.append("")
    body.append("| 指标 | 值 |")
    body.append("|---|---:|")
    body.append("| Extract 文件 | %d |" % summary["extract_files"])
    body.append("| 含图片链接的文件 | %d |" % summary["files_with_links"])
    body.append("| 图片链接总数 | %d |" % summary["image_links"])
    body.append("| 断链 | **%d** |" % summary["broken"])
    body.append("| 断链所在文件 | **%d** |" % summary["files_with_broken"])
    body.append("")
    body.append("**成因**：提取阶段使用 `lit_extract.py --no-images`，Extract 保留了图片占位链接，"
                "但 `references/Extract/assets/` 下没有对应文件。**正文文本不受影响**，"
                "引用正文数字无需修图；本清单是**可读性欠账**，不是证据错误。")
    body.append("")
    body.append("## 二、按文件汇总")
    body.append("")
    body.append("| Extract | 断链数 | 首个目标 |")
    body.append("|---|---:|---|")
    by_file = {}
    for r in rows:
        by_file.setdefault(r["extract"], []).append(r)
    for name in sorted(by_file):
        items = by_file[name]
        body.append("| `%s` | %d | `%s` |" % (name, len(items), items[0]["target"][:90]))
    body.append("")
    body.append("## 三、逐条清单")
    body.append("")
    body.append("| # | Extract | 行 | 目标 |")
    body.append("|---:|---|---:|---|")
    for i, r in enumerate(rows, 1):
        body.append("| %d | `%s` | %d | `%s` |" % (i, r["extract"], r["line"], r["target"]))
    body.append("")
    body.append("## 四、复现")
    body.append("")
    body.append("```bash")
    body.append("python tools/qc_proj_assets.py --project %s --write evidence/extract-image-audit.md"
                % rel_to_vault(project))
    body.append("```")
    body.append("")
    return K.join_frontmatter("\n".join(fm), "\n".join(body))


def rel_to_vault(path):
    try:
        return os.path.relpath(path, VAULT).replace("\\", "/")
    except ValueError:
        return path.replace("\\", "/")


def write_report(project, out_rel, rows, summary, date_str):
    out = out_rel if os.path.isabs(out_rel) else os.path.join(project, out_rel)
    os.makedirs(os.path.dirname(out), exist_ok=True)
    text = render(project, rows, summary, date_str)
    with io.open(out, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    fm_raw, _ = K.split_frontmatter(K.read_text(out))
    if not fm_raw or yaml.safe_load(fm_raw) is None:
        raise RuntimeError("写出后 frontmatter 无法解析：%s" % out)
    return out, len(text)


def selftest():
    ok = 0

    def chk(name, cond):
        nonlocal ok
        if not cond:
            raise AssertionError("FAIL: " + name)
        ok += 1
        print("  [ok] " + name)

    chk("外部链接识别", is_external("https://x/y.png") and not is_external("assets/a.png"))
    with K.temp_dir(prefix="qcproj_assets_") as tmp:
        proj = os.path.join(tmp, "proj")
        ext = os.path.join(proj, EXTRACT)
        os.makedirs(os.path.join(ext, "assets", "ok"))
        good = os.path.join(ext, "assets", "ok", "fig1.png")
        paren = os.path.join(ext, "assets", "ok", "fig(1).png")
        for p in (good, paren):
            with io.open(p, "wb") as f:
                f.write(b"\x89PNG")
        md = "\n".join([
            "# card",
            "![](%s)" % os.path.relpath(good, ext).replace("\\", "/"),
            "![](assets/missing/fig2.png)",
            "![alt text](https://example.com/x.png)",
            "![[assets/ok/fig1.png]]",
            "![](assets/ok/fig(1).png)",
        ])
        with io.open(os.path.join(ext, "Card.md"), "w", encoding="utf-8", newline="\n") as f:
            f.write(md)
        rows, summary = scan(proj)
        chk("断链数 = 1（正例可解析、外链跳过）", summary["broken"] == 1)
        chk("断链行号 = 3", rows and rows[0]["line"] == 3)
        chk("断链目标", rows and rows[0]["target"] == "assets/missing/fig2.png")
        chk("链接总数 = 4（外链不计）", summary["image_links"] == 4)
        chk("目标含成对括号不被截断",
            [t for _, t in iter_md_images("![](assets/ok/fig(1).png)")]
            == ["assets/ok/fig(1).png"])
        out, n = write_report(proj, "evidence/img.md", rows, summary, "2026-10-23")
        chk("报告可写且非空", n > 500)
        chk("报告 frontmatter 可解析",
            yaml.safe_load(K.split_frontmatter(K.read_text(out))[0]) is not None)
    print("selftest OK (%d checks)" % ok)
    return 0


def main(argv=None):
    ap = argparse.ArgumentParser(description="项目 Extract 图片链接审计（只读）")
    ap.add_argument("--project", help="项目目录（含 references/Extract/）")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--write", metavar="REL", help="写 Markdown 报告（相对项目根）")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args(argv)
    if args.selftest:
        return selftest()
    project = args.project
    if not project:
        cands = sorted(glob.glob(os.path.join(VAULT, "projects", "*", EXTRACT)))
        if len(cands) != 1:
            print("[err] 请用 --project 指定项目")
            return 1
        project = os.path.dirname(cands[0])
    if not os.path.isabs(project):
        project = os.path.join(VAULT, project)
    if not os.path.isdir(os.path.join(project, EXTRACT)):
        print("[err] 缺 references/Extract/：%s" % project)
        return 1
    rows, summary = scan(project)
    if args.json:
        print(json.dumps({"summary": summary, "rows": rows}, ensure_ascii=False, indent=2))
    elif args.write:
        out, n = write_report(project, args.write, rows, summary, datetime.date.today().isoformat())
        print("[ok] wrote %s (%d chars)" % (out, n))
        print(json.dumps(summary, ensure_ascii=False, indent=2))
    else:
        print(json.dumps(summary, ensure_ascii=False, indent=2))
        for r in rows[:20]:
            print("  %s:%d  %s" % (r["extract"], r["line"], r["target"]))
    return 0


if __name__ == "__main__":
    sys.exit(main())
